{
  "name": "pairwise_preference_loss",
  "intuition": "This loss captures the preference between two options by favoring pairs where the advantage of the winner over the loser is high, and the cost gap is low. Using logsigmoid on advantage signals emphasizes relative differences, and weighting by 'weight' stabilizes the learning. It encourages the model to rank higher-advantage options more strongly while penalizing less preferred pairs, which aligns with the goal of preference modeling in RL4CO.",
  "pseudocode": "loss = -mean( weight * logsigmoid( advantage_w - advantage_l ) - alpha * cost_gap )",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "advantage",
    "link_family": "logarithmic",
    "agg_family": "pairwise",
    "constraint_family": "margin"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    advantage_w = batch[\"advantage_w\"]\n    advantage_l = batch[\"advantage_l\"]\n    cost_gap = batch.get(\"cost_gap\", ops.zeros_like(advantage_w))\n    preference = ops.logsigmoid(ops.sub(advantage_w, advantage_l))\n    loss = ops.mean(ops.mul(weight, preference)) - alpha * ops.mean(cost_gap)\n    return loss\n"
}

{
  "name": "unnamed_free_loss",
  "intuition": "Added the required expects field listing 'log_prob_w', 'log_prob_l', 'weight', and 'cost_gap' since the loss uses those keys. Simplified the gap calculation by directly using cost_gap from the batch and detached it to avoid gradient flow through costs. Clamped the input to the logsigmoid to [-20,20] to avoid numerical instability. Maintained scaling from the extra hyperparameters for stability. This stabilizes the loss, ensures correct expects, and cleanly focuses on cost_gap with numerical clamping.",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "cost_gap"
    ]
  },
  "generated_loss": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch['weight']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.9496803035382082))\n    gap = batch['cost_gap'].detach()\n    x = alpha * scale * (lpw - lpl) - 0.1 * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    loss = loss * weight\n    return loss.mean()"
}

{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss leverages the advantage signals to prioritize pairs where the advantage difference aligns with the cost gap, encouraging the model to prefer outcomes with lower costs. By focusing on advantage differences conditioned on cost gap, the loss promotes preference consistency with the advantage signals while directly minimizing cost disparity over pairs.",
  "pseudocode": "loss = sum over pairs (logsigmoid(advantage_w - advantage_l + lambda * cost_gap) * weight).",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage",
    "link_family": "logsigmoid",
    "agg_family": "weighted_mean",
    "constraint_family": "cost_difference",
    "other_hparams": "lambda=1.0"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    # Extract signals\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    cost_gap = batch['cost_gap']\n    # Set lambda hyperparameter\n    lambda_val = float(extra.get('lambda', 1.0))\n    # Compute pairwise advantage difference with cost gap\n    signal_diff = ops.sub(advantage_w, advantage_l)\n    cost_term = ops.mul(lambda_val, cost_gap)\n    combined_signal = ops.add(signal_diff, cost_term)\n    # Compute pairwise logsigmoid\n    pairwise_loss = ops.logsigmoid(combined_signal)\n    # Weight the loss\n    weighted_loss = ops.mul(pairwise_loss, weight)\n    # Sum over pairs to get scalar loss\n    return ops.sum(weighted_loss)"
}

