  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    advantage_w = batch[\"advantage_w\"]\n    advantage_l = batch[\"advantage_l\"]\n    cost_gap = batch[\"cost_gap\"]\n    score_diff = advantage_w - advantage_l + alpha * cost_gap\n    loss = -ops.logsigmoid(score_diff) * weight\n    return ops.mean(loss)"
