{
  "name": "loss_rank_gap_tanh_advantage",
  "intuition": "This hyperparameter-only tuning focuses on the hyperparams defining the ranking loss function: the paradigm family, signal family, link family, aggregation family, and constraint family. We keep the core functional structure but explicitly specify these hyperparams to explore variations that emphasize the relative ranking gap normalized by maximum rank, combined with the advantage difference through a tanh activation. The goal is to fine-tune the balance between these components to improve stability and performance, particularly in the context of pairwise preference modeling. The existing structure already encodes the use of rank gap normalization, advantage differences, and a multiplicative tanh link, but it is key to ensure these hyperparameters are explicitly tuned for potential performance gains.",
  "pseudocode": "max_rank = float(batch['log_prob_w'].shape[0])\nrank_w = ops.rank_gap(batch['log_prob_w'], batch['log_prob_l'])\nrank_l = ops.rank_gap(batch['log_prob_l'], batch['log_prob_w'])\n\n# Approximate ranks as argsort + 1 (not directly available, so rely on rank_gap differences)\nrank_diff = rank_w - rank_l\nrank_gap_norm = rank_diff / max_rank  # normalize to [-1, 1]\nadv_gap = batch['advantage_w'] - batch['advantage_l']\nscore = ops.mul(rank_gap_norm, ops.tanh(adv_gap))\nneg_score = ops.relu(ops.neg(score))\nif batch.get('weight', None) is not None:\n    loss = (neg_score * batch['weight']).mean()\nelse:\n    loss = neg_score.mean()\nreturn loss",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_gap",
    "link_family": "multiplicative_tanh",
    "agg_family": "mean",
    "constraint_family": "relu_nonneg"
  },
  "implementation_hint": {
