  "code": "def generated_loss(batch, model_output, extra):\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    logp_w = batch['log_prob_w']\n    logp_l = batch['log_prob_l']\n    weight = batch['weight']\n    adv_diff = ops.sub(adv_w, adv_l)\n    # Use tanh on advantage difference for stable scaling (bounded between -1 and 1)\n    stable_scale = ops.tanh(adv_diff)\n    # Compute score using stable scaled difference and log probs difference\n    score = ops.mul(stable_scale, ops.sub(logp_l, logp_w))\n    # Penalize negative scores to encourage correct preference; zero otherwise\n    loss_per_pair = ops.relu(ops.neg(score))\n    # Apply weights\n    weighted_loss = ops.mul(loss_per_pair, weight)\n    return ops.sum(weighted_loss)"
}

